update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance agroalimentaire","mecanisme":"Des techniciens qui connaissent déjà le lavage haute pression, la marche en avant et les lubrifiants agréés contact alimentaire. Ils arrivent sans semaines d''adaptation, et chaque passage laisse un compte rendu utilisable en audit.","cta":"Faire chiffrer ma maintenance agroalimentaire","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre le reste du temps."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"+ 80","libelle":"clients réguliers, la seule mesure qui compte dans un secteur audité en permanence"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, taux horaire homogène partout"}]},{"type":"probleme","punchline":"La remplisseuse s''arrête un jeudi soir de haute saison. Le produit dans la cuve a une DLC, pas votre prestataire.","puces":[{"accroche":"Un lot au rebut coûte plus cher que la réparation.","texte":"Et la grande distribution ne renégocie pas un déréférencement sur un incident technique."},{"accroche":"Vos équipements vieillissent plus vite qu''ailleurs.","texte":"Lavage haute pression quotidien, produits agressifs, ateliers à 4 °C, condensation. Roulements, capteurs et armoires paient l''addition."},{"accroche":"Le pic saisonnier ne se déplace pas.","texte":"Un conditionnement arrêté en pleine saison coûte bien plus que sa remise en état."},{"accroche":"Un rapport manquant peut coûter une certification, donc un marché.","texte":"La traçabilité n''est pas de la paperasse, c''est votre droit de vendre."},{"accroche":"Un intervenant qui improvise crée le risque corps étranger.","texte":"Outillage oublié, visserie perdue, croisement de flux : la contamination se joue aussi pendant la maintenance."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Techniciens formés aux zones et à la marche en avant","texte":", tenues dédiées par zone, aucun croisement propre et sale."},"benefice":"Aucune règle d''hygiène à rappeler à chaque visite. Votre responsable qualité n''a pas à surveiller l''intervenant."},{"prestation":{"texte":"**Interventions coordonnées avec les plannings de lavage et de production.**"},"benefice":"La maintenance se glisse dans les fenêtres existantes au lieu d''en créer de nouvelles."},{"prestation":{"accroche":"Lubrifiants et consommables agréés contact alimentaire","texte":", référencés dans votre système qualité."},"benefice":"Le choix d''un composant ne remet jamais en cause votre conformité produit."},{"prestation":{"accroche":"Inventaire d''outillage en fin d''intervention","texte":", gestion stricte des pièces et de la visserie."},"benefice":"Le risque corps étranger est traité comme une procédure, pas comme une bonne intention."},{"prestation":{"accroche":"Compte rendu détaillé après chaque passage","texte":", intégrable à votre GMAO et à vos enregistrements qualité."},"benefice":"L''audit IFS ou BRC se prépare sur l''historique existant, sans reconstitution de dernière minute."},{"prestation":{"accroche":"Couverture complète du parc","texte":"remplisseuses, operculeuses, convoyeurs modulaires, cuiseurs, froid industriel, palettiseurs."},"benefice":"Un seul interlocuteur du process au conditionnement, au lieu d''un prestataire par famille de machines."},{"prestation":{"accroche":"Renfort dimensionné avant la haute saison","texte":", puis ajusté à la baisse."},"benefice":"Le pic est absorbé par des techniciens déjà formés au secteur, pas par des heures supplémentaires."}],"prose":[{"texte":"En appui, notre [bureau d''études](/offres/bureau-etudes/) chiffre les améliorations : mise en conformité d''une machine, reprise d''un poste goulot, automatisation d''une opération manuelle arrivée à sa limite."}]},{"type":"deroule","etapes":[{"titre":"Qualification","texte":"un chargé d''affaires étudie votre parc, vos priorités de production et vos contraintes sanitaires. Il annonce ce qui est réaliste, pas ce qui fait plaisir."},{"titre":"Sélection du profil","texte":"un technicien dont l''expérience porte sur des lignes comparables aux vôtres. Résultats de l''évaluation technique et comportementale partagés avant votre décision."},{"titre":"Intégration","texte":"plan de prévention signé, accueil sécurité, habilitations vérifiées, prise en main des protocoles d''hygiène propres à votre site."},{"titre":"Exécution","texte":"préventif calé sur vos fenêtres de lavage et vos cadences, correctif outillé, contrôles tracés à chaque passage."},{"titre":"Traçabilité","texte":"chaque opération alimente votre GMAO au format attendu par votre système qualité. Pièces remplacées, contrôles, tests effectués."},{"titre":"Revue","texte":"statistiques de pannes, disponibilité machine, plan d''amélioration revu avec votre responsable maintenance et votre chef d''atelier."}]},{"type":"garanties","puces":[{"accroche":"La preuve écrite, pas la promesse orale","texte":"chaque passage produit un compte rendu intégrable à vos enregistrements qualité. C''est ce que vos auditeurs demandent, et c''est ce que nous fournissons par défaut."},{"accroche":"Des techniciens déjà exposés au secteur","texte":"10 % des candidats retenus, évaluation technique et comportementale, expérience des ateliers froids et des zones de lavage vérifiée avant l''affectation."},{"accroche":"La conformité des consommables","texte":"produits agréés contact alimentaire quand l''application l''exige, référencés chez vous. Aucun composant introduit sans validation de votre système qualité."}]},{"type":"cta","question":"Besoin d''un technicien qui connaît déjà vos contraintes d''hygiène ?","bouton":"Faire chiffrer ma maintenance agroalimentaire","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Deux techniciens intégrés en 3x8 sur les lignes liquides et poudre, nutrition infantile","texte":"site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Renfort de maintenance sur un site agroalimentaire de grande échelle","texte":"depuis octobre 2024, premier contrat Migen hors de France","lienLibelle":"Étude de cas McCAIN : Belgique","lienHref":"/preuves/mccain-belgique/"},{"titre":"Technicien polyvalent sur un parc hétérogène à forte cadence, papier et emballage","texte":"matière fragile, rythme continu","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Renfort de l''équipe de maintenance pendant les congés d''été","texte":"un technicien sur site, été 2025","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"},{"titre":"Technicien affecté en continu à la fiabilité d''équipements de production en forte activité","texte":"site proche de Paris","lienLibelle":"Étude de cas FDJ : site proche de Paris","lienHref":"/preuves/fdj/"}]},{"type":"objections","questions":[{"question":"Vos techniciens peuvent-ils intervenir pendant la production ?","reponse":"Oui, quand la sécurité le permet. Nous planifions avec votre responsable de production : marche dégradée, pauses de nettoyage, horaires décalés. L''objectif est d''éviter l''arrêt non planifié, pas d''en créer un pour intervenir."},{"question":"Travaillez-vous dans les ateliers froids et les zones humides ?","reponse":"Oui. Nos techniciens sont équipés et habitués aux basses températures, aux zones de lavage et aux atmosphères humides. L''outillage suit les mêmes protocoles d''hygiène que vos équipements, et reste dédié quand la zone l''exige."},{"question":"Comment gérez-vous la traçabilité exigée par nos audits ?","reponse":"Chaque opération donne lieu à un rapport : nature de l''intervention, pièces remplacées, contrôles et tests effectués. Le format s''aligne sur votre GMAO et votre référentiel, qu''il s''agisse d''IFS, de BRC ou de vos procédures internes."},{"question":"Fournissez-vous les pièces détachées ?","reponse":"Nous consultons le marché pour vous au prix réel, avec des références conformes au contact alimentaire quand l''application l''exige. Le stock et le magasin restent sous votre contrôle. Nous vous conseillons sur le stock minimal de pièces critiques à tenir."},{"question":"Pouvez-vous suivre nos pics saisonniers ?","reponse":"Oui, c''est fréquent dans l''alimentaire. Nous renforçons votre équipe avant la haute saison, sur une durée définie, avec des techniciens déjà formés aux contraintes du secteur. Le dispositif s''ajuste à la baisse ensuite, sans nouvelle procédure."},{"question":"Combien coûte une maintenance agroalimentaire externalisée ?","reponse":"Chiffrage après qualification du besoin, taux horaire homogène partout en France, formules à coût prévisible pour le préventif. La comparaison honnête se fait avec le coût réel de vos arrêts et de vos rebuts, pas avec un tarif horaire isolé."}]},{"type":"ctaFinal","question":"Besoin de sécuriser vos lignes avant la prochaine haute saison ?","bouton":"Faire chiffrer ma maintenance agroalimentaire","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/secteurs/agroalimentaire/';
